        print(f"Failed: {failed_count}/{len(results)}")
        for r in results:
            if not r["passed"]:
                print(f"  - {r['check_name']}: {r['message']}")

    return 0 if failed_count == 0 else 1


if __name__ == "__main__":
    sys.exit(main())

